"use client";

import { useTransition } from "react";
import { Trash2 } from "lucide-react";
import { removeCartItem, updateCartItem } from "@/app/actions/cart";

export function CartQty({ itemId, quantity, max }: { itemId: string; quantity: number; max: number }) {
  const [pending, start] = useTransition();
  return (
    <div className="flex items-center gap-3">
      <select
        aria-label="Quantity"
        disabled={pending}
        value={quantity}
        onChange={(e) => start(() => void updateCartItem(itemId, Number(e.target.value)))}
        className="rounded-md border border-line bg-paper px-2 py-1 text-sm"
      >
        {Array.from({ length: Math.max(1, Math.min(max, 20)) }, (_, i) => i + 1).map((n) => <option key={n} value={n}>Qty: {n}</option>)}
      </select>
      <button disabled={pending} onClick={() => start(() => void removeCartItem(itemId))} className="flex items-center gap-1 text-sm text-maroon hover:underline">
        <Trash2 className="h-4 w-4" aria-hidden /> Delete
      </button>
    </div>
  );
}
