"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useMemo, useSyncExternalStore } from "react";
import { formatINR } from "@/lib/money";

type Item = { id: string; slug: string; name: string; price: number; image: string | null };
const KEY = "sm_recent";

function parse(raw: string | null): Item[] {
  try {
    const v = JSON.parse(raw ?? "[]");
    return Array.isArray(v) ? v.slice(0, 12) : [];
  } catch {
    return [];
  }
}

function read(): Item[] {
  try {
    return parse(localStorage.getItem(KEY));
  } catch {
    return [];
  }
}

// localStorage as an external store: snapshot is the raw string, so it is referentially stable.
const subscribe = (cb: () => void) => {
  window.addEventListener("storage", cb);
  window.addEventListener("sm-recent", cb);
  return () => {
    window.removeEventListener("storage", cb);
    window.removeEventListener("sm-recent", cb);
  };
};
const snapshot = () => {
  try {
    return localStorage.getItem(KEY) ?? "[]";
  } catch {
    return "[]";
  }
};

/** Records the current product into the visitor's recently-viewed list (browser only). */
export function RecordView({ item }: { item: Item }) {
  useEffect(() => {
    try {
      const next = [item, ...read().filter((i) => i.id !== item.id)].slice(0, 12);
      localStorage.setItem(KEY, JSON.stringify(next));
      window.dispatchEvent(new Event("sm-recent"));
    } catch {}
  }, [item]);
  return null;
}

export function RecentlyViewed({ excludeId, title = "Your recently viewed items" }: { excludeId?: string; title?: string }) {
  const raw = useSyncExternalStore(subscribe, snapshot, () => "[]");
  const items = useMemo(() => parse(raw).filter((i) => i.id !== excludeId), [raw, excludeId]);
  if (items.length === 0) return null;
  return (
    <section className="animate-fade-in py-6">
      <h2 className="mb-4 font-display text-2xl font-semibold">{title}</h2>
      <div className="no-scrollbar -mx-4 flex gap-3 overflow-x-auto px-4 pb-2 sm:mx-0 sm:px-0">
        {items.map((i) => (
          <Link key={i.id} href={`/product/${i.slug}`} className="group w-36 shrink-0 rounded-xl border border-line bg-white p-2 transition hover:-translate-y-0.5 hover:shadow-md">
            <div className="relative aspect-square rounded-lg bg-paper">
              {i.image && <Image src={i.image} alt="" fill sizes="144px" className="object-contain p-2 transition duration-500 group-hover:scale-105" />}
            </div>
            <p className="mt-2 line-clamp-2 text-xs font-medium group-hover:text-maroon">{i.name}</p>
            <p className="text-sm font-semibold">{formatINR(i.price)}</p>
          </Link>
        ))}
      </div>
    </section>
  );
}
